theorem Exec.compile {k : Nat} {command : Command k} {r : Registers k} {time result}
    (h : Exec command r time result) :
    StackProgram.Exec (compile command) (compile command).start r time result

theorem Exec.machine_run {k : Nat} {command : Command k} {r : Registers k} {time result}
    (h : Exec command r time result) :
    StackMachine.run (machine command) time ⟨(machine command).start, r⟩ = some result

theorem Frame.toBody {k base base' : Nat} {dst : Fin (k + 1)} {r s : Registers k}
    (h : Frame base' dst r s) (hb : base ≤ base')
    (hd : dst = register k 0 ∨ dst = register k 2 ∨ base ≤ dst.val) : BodyFrame base r s

theorem HaltsWithin.mono {N : Machine} {budget budget' : Nat}
    {q : Fin (N.states + 1)} {t : Tape} {post : Bool × Tape → Prop}
    (h : HaltsWithin N budget q t post) (hb : budget ≤ budget') :
    HaltsWithin N budget' q t post

theorem HaltsWithin.post {N : Machine} {budget : Nat}
    {q : Fin (N.states + 1)} {t : Tape} {post post' : Bool × Tape → Prop}
    (h : HaltsWithin N budget q t post) (hp : ∀ result, post result → post' result) :
    HaltsWithin N budget q t post'

theorem HaltsWithin.step {N : Machine} {budget : Nat}
    {q q' : Fin (N.states + 1)} {t : Tape} {a : Symbol} {d : Move}
    {post : Bool × Tape → Prop}
    (hc : N.code q t.read = .step a d q')
    (h : HaltsWithin N budget q' ((t.write a).move d) post) :
    HaltsWithin N (budget + 1) q t post

theorem Room.push {stacks fuel capacity : Nat} {r : StackMachine.Registers stacks}
    (h : Room r (fuel + 1) capacity) (j : Fin (stacks + 1)) (b : Bool) :
    Room (StackMachine.set r j (b :: r j)) fuel capacity

theorem Room.pop {stacks fuel capacity : Nat} {r : StackMachine.Registers stacks}
    (h : Room r (fuel + 1) capacity) (j : Fin (stacks + 1)) :
    Room (StackMachine.set r j (r j).tail) fuel capacity

theorem Status.Equivalent.window {M : Machine} {s s' : Status M}
    (h : s.Equivalent s') (width : Nat) (hsize : s'.tape.size ≤ width) :
    (s.window width).Equivalent s'

theorem exec_result_unique {k : Nat} {p : Command k} {r : Registers k}
    {t s : Nat} {result result'} (h : Exec p r t result) (h' : Exec p r s result') :
    result = result'

theorem evalClause_agrees {n : Nat} {a b : Assignment} {c : Clause}
    (hc : ClauseBelow n c) (hab : AgreesBelow n a b) :
    evalClause a c = evalClause b c

theorem evalCNF_agrees {n : Nat} {a b : Assignment} {f : CNF}
    (hf : CNFBelow n f) (hab : AgreesBelow n a b) :
    evalCNF a f = evalCNF b f

theorem satisfied_flatMap_iff {m d : Nat} {α : Type}
    (v : Valuation m d) (xs : List α) (f : α → Instance m d) :
    Satisfied v (xs.flatMap f) ↔ ∀ a ∈ xs, Satisfied v (f a)

theorem exec_seq_assoc {k : Nat} {a b c : Command k} {r middle : Registers k}
    {t s : Nat} {result} (hab : Exec (.seq a b) r t (true, middle))
    (hc : Exec c middle s result) : Exec (.seq a (.seq b c)) r (t + s) result

theorem Frame.weaken {k base base' : Nat} {dst dst' : Fin (k + 1)}
    {r s : Registers k} (h : Frame base' dst' r s) (hb : base ≤ base')
    (hd : dst' = dst ∨ base ≤ dst'.val) : Frame base dst r s

theorem frame_scratch {k base : Nat} {dst : Fin (k + 1)} {r s : Registers k}
    (h : Frame base dst r s) (hb : 5 ≤ base) (hd : 5 ≤ dst.val)
    (hk : 5 ≤ k + 1) : s (register k 3) = r (register k 3)

theorem CtxOK.extend {n : Nat} {ctx : Fin n → NumExpr 1} {env : Env n} {env0 : Env 1}
    (h : CtxOK ctx env env0) {u : NumExpr 1} {i : Nat} (hi : i ≤ u.eval env0) :
    CtxOK (extendCtx u ctx) (StackTableauEmitter.extend i env) env0

theorem exec_embed (h : k ≤ K) {L : Type} {p : Program k L} {q : L} {r : Registers k} {t : Nat}
    {res : Bool × Registers k} (hx : Exec p q r t res) :
    ∀ R : Registers K, low h R = r → Exec (embed h p) q R t (res.1, merge h R res.2)

theorem take_any_eq_of_map_eq {α β : Type} {f : α → Bool} {g : β → Bool} {xs : List α}
    {ys : List β} (h : xs.map f = ys.map g) (n : Nat) :
    (xs.take n).any f = (ys.take n).any g

theorem gadget_shape {Pt R N : Nat} {σ : Nat → Bool} {L : List Entry}
    (hWF : WF Pt R N σ L) {e : Entry} (he : e ∈ L) :
    ∀ c ∈ gadgetVal Pt R e, (c.length = 2 ∨ c.length = 3) ∧ (c.map Literal.var).Nodup

theorem output_shape {Pt R N : Nat} {σ : Nat → Bool} {L : List Entry}
    (hWF : WF Pt R N σ L) (hR : 2 ≤ R) :
    ∀ c ∈ output Pt R N σ L, (c.length = 2 ∨ c.length = 3) ∧ (c.map Literal.var).Nodup

theorem checkedMachine_polynomial {check : Command 23} {model : Word → Bool} {cc : Nat}
    (hc : CheckSpec check model cc) :
    PolynomialTimeMachine (StackCompile.compile (checkedMachine check))

theorem column_span {W j : Nat} {odd : Bool} {bits : Nat → Nat → Bool × Bool} {c : Clause}
    (hc : c ∈ column W j odd bits) :
    colBase W j ≤ smin c ∧ smin c < smax c ∧ smax c ≤ cellOff W j W + 1

theorem R_columns {W j j' : Nat} {odd odd' : Bool} {bits : Nat → Nat → Bool × Bool}
    {c d : Clause} (hc : c ∈ column W j odd bits) (hd : d ∈ column W j' odd' bits)
    (hne : j ≠ j') : R c d

theorem col_rbEven {W j k v : Nat} {odd : Bool} {bits : Nat → Nat → Bool × Bool} {c d : Clause}
    (hc : c ∈ column W j odd bits) (hpar : odd = true ↔ j % 2 = 1) (hv : v < W)
    (hd : d ∈ rbEven W (2 * k) v) : R c d

theorem col_rbOdd {W j k v : Nat} {odd : Bool} {bits : Nat → Nat → Bool × Bool} {c d : Clause}
    (hc : c ∈ column W j odd bits) (hpar : odd = true ↔ j % 2 = 1) (hv : v < W)
    (hd : d ∈ rbOdd W (2 * k + 1) v) : R c d

theorem mem_cols {W m : Nat} {bits : Nat → Nat → Bool × Bool} {x : Clause}
    (hx : x ∈ colsE W m bits ∨ x ∈ colsO W m bits) :
    ∃ j, j < m ∧ ∃ odd : Bool, (odd = true ↔ j % 2 = 1) ∧ x ∈ column W j odd bits

theorem drop_eq_append {x w : List Bool} {p : Nat}
    (h : ∀ i, i < w.length → x[p + i]? = some w[i]!) :
    x.drop p = w ++ x.drop (p + w.length)

theorem ParseOK.drop_literal {L : Nat} {x : List Bool} {t : ParseTables}
    (h : ParseOK L (fun p => x[p]?) t) {e : Nat} (he : e < t.M) :
    x.drop (t.Q e) = encodeLiteral (t.lit e) ++ x.drop (t.Q e + t.V e + 2)

theorem ParseOK.drop_clause {L : Nat} {x : List Bool} {t : ParseTables}
    (h : ParseOK L (fun p => x[p]?) t) {j : Nat} (hj : j < t.m) :
    x.drop (t.P j) = encodeClause (t.clause j) ++ x.drop (t.P (j + 1))

theorem ParseOK.drop_clauses {L : Nat} {x : List Bool} {t : ParseTables}
    (h : ParseOK L (fun p => x[p]?) t) (hL : x.length = L) :
    ∀ r j, j + r = t.m → x.drop (t.P j) = writeValues encodeClause (t.fml.drop j)

theorem extB_sound {k : Nat} {b : NumExpr 1} {bnd : Fin k → NumExpr 1} {ρ : Env 1} {env : Env k}
    (h : ∀ i, env i ≤ (bnd i).eval ρ) {v : Nat} (hv : v ≤ b.eval ρ) :
    ∀ i, extend v env i ≤ (extB b bnd i).eval ρ

theorem decode_encode (x : List Bool) (c : VCert) (hb : VCert.Bounded x.length c) {τ i : Nat}
    (hτ : τ < 22) (hi : i < tableSize x.length) :
    (decodeCert (pairWords x (encodeCert x.length c)) x.length).tab τ i = c.tab τ i

theorem rprev_mid {A C B : List Nat} (hnd : (A ++ C ++ B).Nodup) (hA : A ≠ []) {p : Nat}
    (hp : p < C.length) :
    rprev (A ++ C ++ B) C[p] = if _hp0 : p = 0 then A.getLast hA
      else C[p - 1]'(by omega)

theorem rprev_top {v p : Nat} (hp : p < (group f true v).length) :
    rprev (rot f v) (2 * (group f true v)[p]) =
      if p = 0 then spE f v else 2 * (group f true v)[p - 1]'(by omega)

theorem rprev_bot {v p : Nat} (hp : p < (group f false (nK f - 1 - v)).length) :
    rprev (rot f v) (2 * (group f false (nK f - 1 - v))[p]) =
      if p = 0 then spW f v else 2 * (group f false (nK f - 1 - v))[p - 1]'(by omega)

theorem flatMap_congr_range {α : Type} {N : Nat} {f g : Nat → List α}
    (h : ∀ i, i < N → f i = g i) :
    (List.range N).reverse.flatMap f = (List.range N).reverse.flatMap g

theorem countP_lt_of_mono {α : Type} {l : List α} {p q : α → Bool}
    (hpq : ∀ a ∈ l, p a = true → q a = true) {y : α} (hy : y ∈ l) (hqy : q y = true)
    (hpy : p y = false) : l.countP p < l.countP q

theorem VSpec.sound {cyc : Bool} {x : Word} {c : VCert}
    (h : VSpec cyc x.length (fun p => x[p]?) c) :
    ∃ f, encode f = x ∧ IsThreeCNF f ∧ Satisfiable f ∧ PlanarGraph (targetGraph cyc f)

theorem targetGraph_end_bound {cyc : Bool} {f : CNF} {d : Nat} {v : Sum Nat Nat}
    (h : halfEdgeEnd (targetGraph cyc f) d = some v) :
    encodeEnd v ≤ 2 * (encode f).length + 1

theorem two_equal {g : Assignment} {x y : Nat}
    (h1 : evalClause g [⟨x, false⟩, ⟨y, true⟩] = true)
    (h2 : evalClause g [⟨x, true⟩, ⟨y, false⟩] = true) : g y = g x

theorem two_equal' {g : Assignment} {x y : Nat}
    (h1 : evalClause g [⟨y, true⟩, ⟨x, false⟩] = true)
    (h2 : evalClause g [⟨y, false⟩, ⟨x, true⟩] = true) : g y = g x

theorem gridAsg_cellClause {j idx : Nat} (h : idx < W) {t : TCl}
    (ht : t ∈ cellT (bits j (row W (par j) idx)).1 (bits j (row W (par j) idx)).2) :
    evalClause (gridAsg W bits a) (inst (cellOff W j idx) (par j) t) = true

theorem gridAsg_column {j : Nat}
    (hsat : ∃ v, v < W ∧ litSat (bits j v).1 (bits j v).2 (a v) = true) {c : Clause}
    (hc : c ∈ column W j (par j) bits) : evalClause (gridAsg W bits a) c = true

theorem grid_complete {W m : Nat} {bits : Nat → Nat → Bool × Bool} {a : Assignment}
    (ha : ∀ j, j < m → ∃ v, v < W ∧ litSat (bits j v).1 (bits j v).2 (a v) = true) :
    evalCNF (gridAsg W bits a) (gridCNF W m bits) = true

theorem run {q : Fin (N.states + 1)} {t : Tape} {cs : List Bool} {q' : Fin (N.states + 1)}
    {t' : Tape} (h : Steps N q t cs q' t') (rest : List Bool) :
    N.run (cs ++ rest) q t = N.run rest q' t'

theorem trans {q : Fin (N.states + 1)} {t : Tape} {cs : List Bool} {q' : Fin (N.states + 1)}
    {t' : Tape} {ds : List Bool} {q'' : Fin (N.states + 1)} {t'' : Tape}
    (h : Steps N q t cs q' t') (h' : Steps N q' t' ds q'' t'') :
    Steps N q t (cs ++ ds) q'' t''

theorem single {c : Bool} {q : Fin (N.states + 1)} {t : Tape} {a : Symbol} {d : Move}
    {q' : Fin (N.states + 1)} (hc : N.code c q t.read = .step a d q') :
    Steps N q t [c] q' ((t.write a).move d)

theorem run_prefix {q : Fin (N.states + 1)} {t : Tape} {cs : List Bool}
    {q' : Fin (N.states + 1)} {t' : Tape} (h : Steps N q t cs q' t') :
    ∀ pre suf : List Bool, cs = pre ++ suf → N.run pre q t = none

theorem equivalent {q : Fin (N.states + 1)} {t : Tape} {cs : List Bool}
    {q' : Fin (N.states + 1)} {t' : Tape} (h : Steps N q t cs q' t') :
    ∀ u : Tape, t.Equivalent u → ∃ u', Steps N q u cs q' u' ∧ t'.Equivalent u'

theorem run_phase_long {N : NMachine} {q : Fin (N.states + 1)} {t : Tape} {n : Nat}
    {P : List Bool → Fin (N.states + 1) → Tape → Prop}
    (h : ∀ cs : List Bool, cs.length = n →
      ∃ q' t', Steps N q t cs q' t' ∧ P cs q' t')
    (cs : List Bool) (hn : n ≤ cs.length) :
    ∃ q' t', P (cs.take n) q' t' ∧ N.run cs q t = N.run (cs.drop n) q' t'

theorem run_phase_short {N : NMachine} {q : Fin (N.states + 1)} {t : Tape} {n : Nat}
    (h : ∀ cs : List Bool, cs.length = n → ∃ q' t', Steps N q t cs q' t')
    (cs : List Bool) (hn : cs.length ≤ n) : N.run cs q t = none

theorem Steps.seqLeft {A B : NMachine} {q : Fin (A.states + 1)} {t : Tape} {cs : List Bool}
    {q' : Fin (A.states + 1)} {t' : Tape} (h : Steps A q t cs q' t') :
    Steps (seq A B) (NTM.seqLeft A B q) t cs (NTM.seqLeft A B q') t'

theorem Steps.seqRight {A B : NMachine} {q : Fin (B.states + 1)} {t : Tape} {cs : List Bool}
    {q' : Fin (B.states + 1)} {t' : Tape} (h : Steps B q t cs q' t') :
    Steps (seq A B) (NTM.seqRight A B q) t cs (NTM.seqRight A B q') t'

theorem assignmentOf_eq {occ : List (BinaryLiteral × Bool)}
    (hc : consistent (occ.map entry) = true) {p : BinaryLiteral × Bool} (hp : p ∈ occ) :
    assignmentOf occ (binaryValue p.1.bits) = p.2

theorem exec_embedded {k k' : Nat} {L : Type} (h : k ≤ k') (p : Program k L)
    {q : L} {R : Registers k'} {t : Nat} {b : Bool} {r : Registers k}
    (he : Exec p q (restrict h R) t (b, r)) : Exec (embed h p) q R t (b, extend h R r)
